Plan:
Parse each Amount string in B2:B5 by removing currency letters and spaces, infer the decimal separator from the last separator and digit count, then convert to a float. Write the rounded numeric results into C2:C5 of the active sheet. Save the workbook as OUT.

```python
import shutil
import re
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals.active

def parse_amount(value):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)

    t = str(value).strip()
    if not t:
        return None

    # Remove currency codes / letters, then keep only numeric separators and sign.
    t = re.sub(r"[A-Za-z]+", "", t)
    t = re.sub(r"[^0-9.,\-]", "", t)

    if not t:
        return None

    # Handle a trailing minus sign, e.g. "1,23-".
    if t.endswith("-"):
        t = "-" + t[:-1]

    last_dot = t.rfind(".")
    last_comma = t.rfind(",")

    if last_dot != -1 and last_comma != -1:
        if last_dot > last_comma:
            dec, thou = ".", ","
        else:
            dec, thou = ",", "."
    elif last_comma != -1:
        # One comma followed by 1-2 digits at the end is treated as decimal.
        if t.count(",") == 1 and re.search(r",\d{1,2}$", t):
            dec, thou = ",", "."
        else:
            dec, thou = ".", ","
    elif last_dot != -1:
        # One dot followed by 1-2 digits at the end is treated as decimal.
        if t.count(".") == 1 and re.search(r"\.\d{1,2}$", t):
            dec, thou = ".", ","
        else:
            dec, thou = ",", "."
    else:
        dec = thou = None

    if dec:
        if thou:
            t = t.replace(thou, "")
        t = t.replace(dec, ".")

    # Safety: if multiple dots remain, keep only the last one as decimal.
    if t.count(".") > 1:
        idx = t.rfind(".")
        t = t[:idx].replace(".", "") + t[idx:]

    try:
        return float(t)
    except ValueError:
        return None

for r in range(2, 6):
    raw = vws.cell(row=r, column=2).value
    num = parse_amount(raw)
    if num is None:
        ws.cell(row=r, column=3).value = None
    else:
        ws.cell(row=r, column=3).value = round(num, 2)
    print(r, repr(raw), "->", ws.cell(row=r, column=3).value)

wb.save(OUT)
